INSERT INTO `beritas` (`id`, `judul`, `slug`, `ringkasan`, `isi`, `gambar`, `tanggal`, `created_at`, `updated_at`) VALUES
	(1, 'Tampil rapi adalah langkah awal untuk belajar dengan baik.', 'siswa-raih-juara-1-olimpiade-sains-tingkat-provinsi', 'Disiplin dimulai dari hal-hal sederhana. Mari bersama ciptakan budaya sekolah yang tertib, nyaman, dan membanggakan', 'Pastikan selalu mengenakam seragam sesuai jadwal yang telah ditentukan dan teteap menjaga kerapihan serta kebersihan.', 'berita/KMCSd8NMdwHBpy2b4mqObjYiqe28EZPj6xB4wtog.jpg', '2026-07-10', '2026-08-01 06:56:01', '2026-08-08 00:39:52'),
	(2, 'Penerimaan Tamu Ambalan (PTA) 2026 SMKN 1 CIJATI', 'pelaksanaan-ujian-tengah-semester-ganjil-berjalan-lancar', 'Setiap langkah adalah awal. Setiap pengalaman adalah bekal.', 'Selama 2 hari 1 malam di Bumi Perkemahan Lapangan Parakan Tugu, seluruh peserta mengikuti rangkaian kegiatan yang dirancang untuk membangun karakter, mempererat persaudaraan, sereta menumbuhkan jika kepemimpinan dan kepedulian terhadap sesama maupun lingkungan.', 'berita/Cpc5VHB2aqs5ukVMW2YATB5VQ3xzHpr6KS2DqbZy.jpg', '2026-07-29', '2026-08-01 06:56:01', '2026-08-08 00:26:01'),
	(3, 'JATIZI FUN RUN 2026', 'kegiatan-bakti-sosial-peringati-hari-pendidikan-nasional', 'JATIZI Berlai, Sehat Menginspirasi', 'Dalam rangka memperingati Hari Pendidikan Nasional, seluruh warga sekolah mengadakan kegiatan bakti sosial berupa pembagian sembako dan alat tulis kepada masyarakat sekitar.', 'berita/3u5n85sjM5VHFLSHV89ArkGIvETWSGllSglkokHs.jpg', '2026-06-23', '2026-08-01 06:56:01', '2026-08-08 00:27:50'),
	(4, 'FLS3N SMKN 1 CIJATI 2026', 'workshop-literasi-digital-untuk-guru-dan-siswa', 'FLS3N adalah panggung untuk berkarya, berani tampil, dan menunjukkan potensi terbaik.', 'Perwakilan SMKN 1 CIijati siap melangkah dengan semangat dan kerja keras untuk memberikan yang terbaik.', 'berita/vwo2kcfv3Xc8cE9WG9RB0eZLMWJJhfyin5wtpK1x.jpg', '2026-02-22', '2026-08-01 06:56:01', '2026-08-08 00:32:22'),
	(5, 'MPLS PANCAWALUYA 2026', 'mpls-pancawaluya-2026-1786179183', 'Langkah pertama telah dimulai', 'Selamat datang di keluraga besar SMKN 1 Cijati. Mari jadikan setiap langkah di sekolah ini sebgaai awal menuju masa depan yang lebihbaik.', 'berita/lryKH3GkeHxKdgFgt2uwGLSzw42m132SOqclpc8Z.jpg', '2026-12-07', '2026-08-08 01:53:04', '2026-08-08 01:53:04'),
	(6, 'CLASSMEETING 2026', 'classmeeting-2026-1786365148', 'Momen Kebersamaan dalam Class Meeting 2026', 'Setiap pertandingan dna perlombaan bukan hanya tentang siapa yang menjadi juara, tetapi tentang semangat, kerja sama, dan penglaaman berharga yang tercipta bersama.', 'berita/VXbZDbu2L4HRzncD8vPDKuWAz5DNinBgmCVzyXeL.jpg', '2026-08-10', '2026-08-10 05:32:29', '2026-08-10 05:32:29'),
	(7, 'Pesantren Ekologi', 'pesantren-ekologi-1786365613', 'Pesantren Ekologi SMKN 1 CIJATI, BERSIH HATI, BERSIH BADAN, BERSIH LINGKUNGAN.', 'Pesantren Ekologi SMKN 1 CIJATI, BERSIH HATI, BERSIH BADAN, BERSIH LINGKUNGAN.', 'berita/N39R4JYFcRGfTJ8pqaKR8Jy8KtXDoaym1luFZdDt.jpg', '2026-08-10', '2026-08-10 05:40:13', '2026-08-10 05:40:55'),
	(8, 'Upacara 17 Agustus 2026', 'upacara-17-agustus-2026-1787190583', 'Pasukan pengibar bendera tingkat kecamatan cijati', 'Upacara Peringatan  Hari Ulang Tahun ke-81 Republik Indonesia Tingkat Kecamatan Cijati.\r\nMomentum ini menjadi pengingat bahwa kemerdekaan adalah hasil perjuangan yang harus dijaga melalui persatuan, semangat gotong royong, dan kontribusi nyata bagi bangsa.', 'berita/b9emZZrwTHfZpbbKCwzzvlFN7sBKOPwL6xEycSno.jpg', '2026-08-17', '2026-08-19 18:49:45', '2026-08-19 18:49:45'),
	(9, 'LSPMI', 'lomba-17-smk-negeri-1-cijati-2026-1787190775', 'Dalam memeriahkan HUT ke-81 Republik Indonesia', 'Ujian LSPMI', 'berita/hRbRdfD3Yx777l38vaF5e9dxTCEteRmBi1n0ueRL.jpg', '2026-12-08', '2026-08-19 18:52:55', '2026-09-16 22:34:21'),
	(10, 'Selamat dan Sukses', 'selamat-dan-sukses-1787191378', 'SMKN 1 Cijati, bangga atas pencapaian kalian', 'Selamat Kepada 14 peserta didik SMKN 1 Cijati yang telah resmi dikukuhkan sebagai Pasukan Pengibar Bendera Tingkat Kecamatan Cijati Tahun 2026.', 'berita/sukXrRfl8XNAaDOJkfkMG69nMUhK3dKKm5UXYvrL.jpg', '2026-08-20', '2026-08-19 19:02:58', '2026-08-19 20:58:28');
INSERT INTO `ekstrakurikulers` (`id`, `nama`, `deskripsi`, `gambar`, `pembina`, `jadwal`, `icon`, `created_at`, `updated_at`) VALUES
	(1, 'Futsal', 'Melatih sportivitas, kerja sama tim, dan fisik yang tangguh melalui latihan rutin dan kompetisi antarsekolah.', 'ekstrakurikuler/futsal.jpg', 'Jaya Nur Setiawandi, S.Pd', 'Rabu & Kamis, 15.30 - 17.00', 'bi-trophy', '2026-08-01 06:56:00', '2026-08-10 05:13:14'),
	(2, 'Karawitan', 'Wadah ekspresi kreatif siswa dalam seni peran, musik, dan visual, dengan pementasan rutin setiap semester.', 'ekstrakurikuler/kegiatan_karawitan.jpeg', 'Yoga Agung, M.Pd', 'Rabu, 15.30 - 17.00', 'bi-music-note-beamed', '2026-08-01 06:56:00', '2026-08-01 06:56:00'),
	(3, 'Cinemak', 'Eksplorasi teknologi dan pengembangan informasi berbasis digital.', 'ekstrakurikuler/kegiatan_cinemak.jpeg', 'Rahmat Setiawan, S.T.', 'Senin, 14.00 - 16.00', 'bi-camera-reels', '2026-08-01 06:56:00', '2026-08-01 06:56:00'),
	(4, 'Pramuka', 'Membentuk jiwa kepemimpinan, kemandirian, dan kepedulian sosial melalui kegiatan alam terbuka.', 'ekstrakurikuler/kegiatan_pramuka.jpeg', 'Najib Aminullah', 'Jumat, 08.00 - 11.00', 'bi-tree', '2026-08-01 06:56:00', '2026-08-01 06:56:00'),
	(5, 'Marching Band', 'Mengasah kemampuan vokal dan harmoni bermusik, tampil dalam berbagai acara resmi sekolah.', 'ekstrakurikuler/kegiatan_marching_band.jpeg', 'Ibu. Nurah Alwaini', 'Sabtu, 15.30 - 17.00', 'bi-megaphone', '2026-08-01 06:56:00', '2026-08-01 06:56:00'),
	(6, 'Bahasa Jepang', 'Meningkatkan kepercayaan diri berbahasa Jepang melalui debat, drama, dan diskusi tematik.', 'ekstrakurikuler/Ic5pwv2CYbpl5KZhjrmfORvyQkcNJMJo1fh9DiOU.webp', 'Bpk. Saripul Basar', 'Senin, 15.30 - 17.00', 'bi-translate', '2026-08-01 06:56:00', '2026-09-11 07:24:06'),
	(7, 'PMR', 'Melatih sportivitas, kerja sama tim, dan fisik yang tangguh melalui latihan rutin dan kompetisi antarsekolah.', 'ekstrakurikuler/kegiatan_pmr.jpeg', 'Mega Nurunisa, S.Pd', 'Selasa, 15.30 - 17.00', 'bi-heart-pulse', '2026-08-01 06:56:00', '2026-08-01 06:56:00'),
	(8, 'Paskibra', 'Melatih sportivitas, kerja sama tim, dan fisik yang tangguh melalui latihan rutin dan kompetisi antarsekolah.', 'ekstrakurikuler/kegiatan_paskibra.jpeg', 'Ende Iskandar, S.Tp', 'Selasa, 15.30 - 17.00', 'bi-flag', '2026-08-01 06:56:00', '2026-08-01 06:56:00'),
	(9, 'Rohis', 'Melatih sportivitas, kerja sama tim, dan fisik yang tangguh melalui latihan rutin dan kompetisi antarsekolah.', 'ekstrakurikuler/kegiatan_rohis.jpeg', 'Bpk. Asep Mukhlis, S.Pd', 'Kamis, 15.30 - 17.00', 'bi-moon-stars', '2026-08-01 06:56:00', '2026-08-10 05:14:36'),
	(10, 'Volly', 'Melatih sportivitas, kerja sama tim, dan fisik yang tangguh melalui latihan rutin dan kompetisi antarsekolah.', 'ekstrakurikuler/kegiatan_volly.jpeg', 'Bpk. Dedi Sukardi, S.Pd', 'Senin & Selasa, 15.30 - 17.00', 'bi-circle', '2026-08-01 06:56:00', '2026-08-10 05:13:42');
