INSERT INTO `jurusans` (`id`, `nama`, `singkatan`, `slug`, `deskripsi`, `kompetensi`, `kepala_program`, `foto_kepala_program`, `foto_sampul`, `icon`, `created_at`, `updated_at`) VALUES
	(1, 'Rekayasa Perangkat Lunak', 'RPL', 'rpl', 'Jurusan yang mempelajari perancangan, pembuatan, dan pengembangan perangkat lunak (software), mulai dari aplikasi web, aplikasi mobile, hingga sistem informasi.', 'Pemrograman web (HTML, CSS, JavaScript, PHP)\r\nPemrograman aplikasi mobile\r\nBasis data (database)\r\nStruktur data & algoritma\r\nPengujian & debugging perangkat lunak', 'Rahmat Setiawan, S.T', 'jurusan/w9shx5vM4dva1hcKAGP3lOIzwBeS9g6uLo3rEa1V.webp', 'jurusan/oMCaVKBgqf3H3rTis6hUxi2nQ6iCoSQy8pdu12SI.webp', 'bi-code-slash', '2026-08-05 21:29:40', '2026-08-27 06:22:27'),
	(2, 'Agribisnis Pengolahan Hasil Pertanian', 'APHP', 'aphp', 'Jurusan yang mempelajari cara mengolah hasil pertanian, perkebunan, dan peternakan menjadi produk pangan yang bernilai jual dan siap dipasarkan.', 'Teknik pengolahan hasil pertanian\r\nPengemasan & pelabelan produk\r\nPengendalian mutu pangan\r\nKewirausahaan produk olahan\r\nSanitasi & keamanan pangan', 'Budiana Hermawan, S.Tp', 'jurusan/91dOXj22PLa27lnhcBHvx1CZ4GBmwmX094p2YkZU.webp', 'jurusan/2Pjp9wdd3XwnSlMhDEgHZFcAxi8m5ktUwSJSE6BO.webp', 'bi-basket', '2026-08-05 21:29:40', '2026-08-27 06:21:51'),
	(3, 'Teknik Otomotif', 'TO', 'to', 'Jurusan yang mempelajari perawatan, perbaikan, dan pemeliharaan kendaraan bermotor, mulai dari sistem mesin, kelistrikan, hingga sasis kendaraan.', 'Perawatan & perbaikan mesin kendaraan\r\nSistem kelistrikan otomotif\r\nSistem pemindah tenaga\r\nChassis & pemindah daya\r\nK3 (Keselamatan & Kesehatan Kerja) bengkel', 'Romi Darmayadi, S.T', 'jurusan/T0LDgnui4W12k4kYVtsxCclInc1raNavzQrVySoQ.webp', 'jurusan/baDg0sFyWb8E2TFrhFFZivuTzQCfRhlzZ9n8EL6a.webp', 'bi-wrench-adjustable', '2026-08-05 21:29:40', '2026-08-27 06:22:45'),
	(4, 'Bisnis Daring dan Pemasaran', 'BDP', 'bdp', 'Jurusan yang mempelajari strategi pemasaran, penjualan, dan bisnis digital — mempersiapkan siswa untuk berwirausaha maupun bekerja di bidang pemasaran modern.', 'Pemasaran digital (digital marketing)\r\nAdministrasi transaksi\r\nPengelolaan bisnis online\r\nKomunikasi bisnis\r\nKewirausahaan', 'Indra Murgianto, S.Pd', 'jurusan/cDsqhAGcNMtkcsVnkxmiOP8MG07eJq46nqVQCdjL.png', 'jurusan/HgpbxBEeov9gOqBxshBvN87aovsrqsJwerUllvjy.webp', 'bi-graph-up-arrow', '2026-08-05 21:29:40', '2026-08-27 06:22:09');
