INSERT INTO `profil_sekolahs` (`id`, `nama_sekolah`, `motto`, `sambutan_kepala_sekolah`, `nama_kepala_sekolah`, `visi`, `misi`, `sejarah`, `alamat`, `telepon`, `email`, `npsn`, `status`, `akreditasi`, `website`, `instagram`, `facebook`, `youtube`, `jumlah_siswa`, `jumlah_guru`, `jumlah_kelas`, `tahun_berdiri`, `created_at`, `updated_at`) VALUES
	(1, 'SMK Negeri 1 Cijati', 'Cageur, Bageur, Bener, Pinter, Singer.', 'Selamat datang di SMK Negeri 1 Cijati. Kami berkomitmen membentuk generasi yang cerdas, berkarakter, dan siap menghadapi tantangan masa depan melalui pembelajaran yang bermakna dan menyenangkan.', 'A Rahmat Dimyati, S.Pd., M.Pd', 'Menjadi lembaga pendidikan unggul yang melahirkan generasi cerdas, berkarakter, dan berdaya saing global. Terwujdnya SMKN 1 Cijati Sebagai Pusat Pelatihan\r\nKejuruan Yang Mampu Melayani Dalam Berbagai Kejuruan\r\nSesuai Dengan Tuntutan Kebutuhan Lokal,\r\nNasional, dan Internasional Pada Tahun 2023', 'Menyelenggarakan pembelajaran yang aktif, kreatif, dan menyenangkan.\nMembina karakter siswa berlandaskan nilai kejujuran dan disiplin.\nMengembangkan potensi siswa melalui kegiatan akademik dan non-akademik.\nMenjalin kerja sama dengan orang tua dan masyarakat.', 'Berawal dari keinginan kuat dari seorang Pendidik bernama H. Dede Kartiman yang menginginkan adanya pemerataan pendidikan menengah kejuruan untuk daerah-daerah yang terpencil terutama Kecamatan Cijati yang terletak di Kabupaten Cianjur serta dukungan masyarakat sekitar lingkungan kecamatan Cijati yang menginginkan jenjang pendidikan menengah kejuruan di wilayahnya yang hingga saat ini merupakan para pendiri SMK Negeri 1 Cijati. Bekerja sama dengan Dinas Pendidikan Kabupaten Cianjur mengajukan permohonan pendirian SMK Negeri 1 Cijati kepada Bupati Kabupaten Cianjur.\r\n\r\nPada awalnya SMK Negeri 1 Cijati itu merupakan kelas jauh dari SMK Negeri 2 Cilaku, hanya membuka program jurusan keahlian Teknologi Pengolahan Hasil Pertanian (TPHP) memiliki lahan seluas 1 ha yang merupakan hibah dari salah seorang masyarakat Cijati hingga pada akhirnya SMK Negeri 1 Cijati berdiri secara resmi sejak tanggal 19 September 2006 berdasarkan Surat Keputusan BUPATI Kabupaten Cianjur Nomor: 421.5/Kep.179-Ks/2006 mengenai Pendirian Sekolah Menengah Kejuruan di wilayah kecamatan Cijati.\r\n\r\nMelihat perkembangan baik kuantitas maupun kualitas di SMK Negeri 1 Cijati yang maju, maka pada Tahun Pelajaran berikutnya yaitu Tahun 2007, SMK Negeri 1 Cijati membuka program jurusan keahlian yang baru yaitu Pemasaran (TN) dan Rekayasa Perangkat Lunak (RPL), serta penambahan program jurusan keahlian Teknik Kendaraan Ringan (TKR) pada bulan Juli 2013.', 'Jl. Karang Anyar, Desa. Cijati, Kecamatan. Cijati, Kabupaten. Cianjur, Provinsi. Jawa Barat', '085860639317', 'info@smkn1cijati.sch.id', '20252505', 'Negeri', 'A', 'http://smkn1cijati.sch.id/', 'https://www.instagram.com/smkn1cijatiofficial/', 'https://www.facebook.com/share/17GCBS8JYb/', 'https://youtube.com/@smkn1cijatiofficial?si=oKnay2WjT2xpSluQ', 663, 52, 24, 2008, '2026-08-01 06:56:00', '2026-09-02 19:16:35');
